import com.alibaba.fastjson2.JSON;
import com.alibaba.fastjson2.JSONFactory;
import com.alibaba.fastjson2.JSONReader;
import com.alibaba.fastjson2.reader.ObjectReader;
import com.alibaba.fastjson2.reader.ObjectReaderProvider;
import com.alibaba.fastjson2.util.Fnv;

import java.lang.ref.WeakReference;
import java.lang.reflect.Field;
import java.net.URL;
import java.net.URLClassLoader;
import java.nio.file.Paths;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Reproduces: an @type payload resolved through an AutoTypeBeforeHandler into a class from a
 * dynamic loader ends up in ObjectReaderProvider.hashCache; cleanup(ClassLoader) cannot remove it;
 * removing that entry releases the loader.
 */
public class HashCacheFixProbe {
    public static void main(String[] args) throws Exception {
        WeakReference<ClassLoader> ref = runScenario(Paths.get(args[0]).toUri().toURL());
        for (int i = 0; i < 5 && ref.get() != null; i++) {
            System.gc();
            Thread.sleep(50);
        }
        System.out.println("[5] loader collected after sweep (best-effort): " + (ref.get() == null));
    }

    static WeakReference<ClassLoader> runScenario(URL pojoUrl) throws Exception {
        URLClassLoader loader = new URLClassLoader(new URL[]{pojoUrl}, null);
        Class<?> pojoClass = Class.forName("probe.TestPojo", false, loader);

        ObjectReaderProvider provider = JSONFactory.getDefaultObjectReaderProvider();
        JSONReader.AutoTypeBeforeHandler oldHandler = provider.getAutoTypeBeforeHandler();
        provider.setAutoTypeBeforeHandler((typeName, expectClass, features) ->
                "probe.TestPojo".equals(typeName) ? pojoClass : null);

        ClassLoader oldTcc = Thread.currentThread().getContextClassLoader();
        Thread.currentThread().setContextClassLoader(loader);

        Object result = JSON.parseArray("[{\"@type\":\"probe.TestPojo\",\"x\":7}]");
        List<?> parsedList = (List<?>) result;
        System.out.println("[1] parse ok, element class: " + parsedList.get(0).getClass().getName());

        Field hashCacheField = ObjectReaderProvider.class.getDeclaredField("hashCache");
        hashCacheField.setAccessible(true);
        ConcurrentHashMap<Long, ObjectReader> hashCache =
                (ConcurrentHashMap<Long, ObjectReader>) hashCacheField.get(provider);
        long nameHash = Fnv.hashCode64("probe.TestPojo");
        ObjectReader cached = hashCache.get(nameHash);
        System.out.println("[2] hashCache entry present: " + (cached != null)
                + ", reader.objectClass == dynamic class: "
                + (cached != null && cached.getObjectClass() == pojoClass));

        Field tclField = ObjectReaderProvider.class.getDeclaredField("tclHashCaches");
        tclField.setAccessible(true);
        ConcurrentHashMap<Integer, ConcurrentHashMap<Long, ObjectReader>> tclHashCaches =
                (ConcurrentHashMap<Integer, ConcurrentHashMap<Long, ObjectReader>>) tclField.get(provider);
        ConcurrentHashMap<Long, ObjectReader> tclBucket = tclHashCaches.get(System.identityHashCode(loader));
        System.out.println("[2b] tclHashCaches bucket present: " + (tclBucket != null)
                + ", has name entry: " + (tclBucket != null && tclBucket.get(nameHash) != null));

        provider.cleanup(loader);
        cached = hashCache.get(nameHash);
        tclBucket = tclHashCaches.get(System.identityHashCode(loader));
        System.out.println("[3] after cleanup(ClassLoader): "
                + "hashCache still present: " + (cached != null)
                + ", tcl bucket: " + (tclBucket != null));

        int removed = 0;
        for (Map.Entry<Long, ObjectReader> e : hashCache.entrySet()) {
            ObjectReader r = e.getValue();
            if (r != null && r.getObjectClass() != null && r.getObjectClass().getClassLoader() == loader) {
                hashCache.remove(e.getKey());
                removed++;
            }
        }
        System.out.println("[4] reflective sweep removed: " + removed
                + ", hashCache entry now: " + (hashCache.get(nameHash) != null));

        provider.setAutoTypeBeforeHandler(oldHandler);
        Thread.currentThread().setContextClassLoader(oldTcc);
        return new WeakReference<>(loader);
    }
}
```

