      id:'group1',
      type: 'multiple',
      items: [
        {
          xAxisId: 'xAxis-1',
          top:0,
          height'45%',
          padding:'5%'
        },
        {
          xAxisId: 'xAxis-1',
          top:'50%',
          height'45%',
          padding:'5%'
        },
        {
          //...
        }
      ]
    }
  ],
  series: [
    {
      xAxisId: 'xAxis-1',
      group: 'group1',
      data: []
    },
    {
