      HoodieWriteMetadata result = c.logCompact(instant.get());
      c.commitLogCompaction(instant.get(), result, Option.empty());
      stage = "verify";
      List<String> after = snapshot(path);
      if (!before.equals(after)) throw new AssertionError("Snapshot changed: " + after);
      if (expectNpe) throw new AssertionError("Expected reproduction missing");
      if (cdcBefore != null && !cdcBefore.equals(cdcRows(path))) throw new AssertionError("CDC changed after log compaction");
      System.out.println("CASE_RESULT=" + name + " PASS snapshot unchanged rows=" + after.size());
      validatedCases++;
    } catch (Throwable t) {
      System.out.println("CASE_RESULT=" + name + " FAIL stage=" + stage);
      t.printStackTrace(System.out);
      List<String> after = snapshot(path);
      System.out.println("SNAPSHOT_AFTER_FAILURE=" + after);
      if (!expectNpe || !stage.equals("schedule") || !hasNpe(t)) throw new AssertionError("Unexpected failure", t);
      if (!before.equals(after)) throw new AssertionError("Snapshot changed after failure");
      if (cdcBefore != null && !cdcBefore.equals(cdcRows(path))) throw new AssertionError("CDC changed after failure");
      System.out.println("EXPECTED_NPE_VERIFIED=" + name + " snapshot_and_available_CDC_unchanged");
      validatedCases++;
    }
  }
}

```
