QUERY label=cdc_off_logcompaction_plus_write reader=default begin=20261014110624974 end=20261014110627053 count=1 rows=[{"id":"a","ts":4,"value":"a4","part":"p","_hoodie_commit_time":"20261014110626675"}]
QUERY label=cdc_off_regular_compaction_only reader=default begin=20261014110627951 end=20261014110628270 count=0 rows=[]
QUERY label=cdc_off_historical_after_regular reader=default begin=20261014110624974 end=20261014110625352 count=0 rows=[]
QUERY label=cdc_off_historical_after_clean reader=default begin=20261014110624974 end=20261014110625352 count=1 rows=[{"id":"b","ts":3,"value":"b3","part":"p","_hoodie_commit_time":"20261014110624974"}]
SNAPSHOT_METADATA_AFTER=[{"id":"a","_hoodie_commit_time":"20261014110632061"}, {"id":"b","_hoodie_commit_time":"20261014110632061"}]
TIMELINE requested=20261014110632061 completion=20261014110632394 action=deltacommit operation=LOG_COMPACT numWrites=2 numUpdates=2
```

**Source analysis (not a patched/tested fix):**

In release-1.2.1, [FileGroupReaderBasedAppendHandle's constructor](https://github.com/apache/hudi/blob/release-1.2.1/hudi-client/hudi-client-common/src/main/java/org/apache/hudi/io/FileGroupReaderBasedAppendHandle.java#L67) calls the ordinary `HoodieAppendHandle` constructor. That path does not set the private `isLogCompaction` flag, whereas the older dedicated log-compaction constructor does. [populateMetadataFields](https://github.com/apache/hudi/blob/release-1.2.1/hudi-client/hudi-client-common/src/main/java/org/apache/hudi/io/HoodieAppendHandle.java#L327) therefore replaces record commit time/sequence metadata with the service instant. The observed snapshot metadata and later base-file fallback result are consistent with this constructor path. Please cover both commit-time preservation and delayed incremental reads in a fix.

### Standalone reproducer

Save the source below as `LogCompactionIncrementalRepro.java`. With Java 11 and `REPRO_CP` containing Spark SQL + Spark Hive 3.5.6 runtime dependencies, commons-logging 1.2, protobuf-java 3.25.5 and exactly one matching Hudi Spark 3.5/Scala 2.12 bundle:

```sh
mkdir -p evidence classes
javac -cp "$REPRO_CP" -d classes LogCompactionIncrementalRepro.java
SPARK_LOCAL_IP=127.0.0.1 java -Xmx3g -cp "classes:$REPRO_CP" LogCompactionIncrementalRepro
# For the 1.2.1 table-version-8 variant, add -Drepro.table.version=8 before -cp.
```

The harness creates disposable local tables under `evidence/` and cleans only those tables. It prints observed query rows, service metadata and query plans; it checks normal-write and regular-compaction controls and business-value preservation. `TEST_COMPLETED` indicates the harness completed; a nonzero `duplicate_windows` count records reproduced failures rather than a passing correctness test. External checks verified the counts shown in the result table for every reader/CDC combination.

<details>
<summary>Complete Java reproducer</summary>

```java
import java.nio.file.*;
import java.util.*;
import java.util.stream.*;
import org.apache.spark.sql.*;
import org.apache.spark.api.java.JavaSparkContext;
import org.apache.hudi.client.SparkRDDWriteClient;
import org.apache.hudi.client.common.HoodieSparkEngineContext;
import org.apache.hudi.common.table.HoodieTableMetaClient;
import org.apache.hudi.common.table.TableSchemaResolver;
import org.apache.hudi.common.table.timeline.HoodieInstant;
import org.apache.hudi.common.table.timeline.HoodieTimeline;
import org.apache.hudi.common.model.HoodieCommitMetadata;
import org.apache.hudi.common.util.Option;
import org.apache.hudi.config.HoodieWriteConfig;
import org.apache.hudi.hadoop.fs.HadoopFSUtils;
import org.apache.hudi.table.action.HoodieWriteMetadata;
public class LogCompactionIncrementalRepro {
  static SparkSession spark;
  static JavaSparkContext jsc;
  static Path root;
  static int duplicates;
  static int queries;
  public static void main(String[] args) throws Exception {
    TimeZone.setDefault(TimeZone.getTimeZone("UTC"));
    root=Files.createTempDirectory(Paths.get("evidence"),"tables-").toAbsolutePath();
    System.out.println("EVIDENCE_ROOT="+root);
    System.out.println("HUDI_RUNTIME="+SparkRDDWriteClient.class.getProtectionDomain().getCodeSource().getLocation());
    spark=SparkSession.builder().master("local[2]").appName("hudi-logcompaction-incremental-repro")
      .config("spark.driver.host","127.0.0.1").config("spark.driver.bindAddress","127.0.0.1")
      .config("spark.ui.enabled","false").config("spark.sql.shuffle.partitions","1")
      .config("spark.default.parallelism","1").config("spark.serializer","org.apache.spark.serializer.KryoSerializer")
      .config("spark.sql.extensions","org.apache.spark.sql.hudi.HoodieSparkSessionExtension")
      .config("spark.sql.catalog.spark_catalog","org.apache.spark.sql.hudi.catalog.HoodieCatalog")
      .config("spark.sql.adaptive.enabled","false").getOrCreate();
    spark.sparkContext().setLogLevel("ERROR");
    jsc=JavaSparkContext.fromSparkContext(spark.sparkContext());
    try { runCase(false); runCase(true); System.out.println("TEST_COMPLETED queries="+queries+" duplicate_windows="+duplicates); }
    finally {spark.stop();}
  }
  static String schema(String path) throws Exception {
    TableSchemaResolver resolver=new TableSchemaResolver(meta(path));
    try {return resolver.getClass().getMethod("getTableSchema").invoke(resolver).toString();}
    catch (NoSuchMethodException e) {return resolver.getClass().getMethod("getTableAvroSchema").invoke(resolver).toString();}
  }
  static Map<String,String> options(String name, boolean cdc) {
    Map<String,String> p = new HashMap<>();
    p.put("hoodie.table.name", name);
    if (System.getProperty("repro.table.version") != null) p.put("hoodie.write.table.version",System.getProperty("repro.table.version"));
    p.put("hoodie.datasource.write.table.type", "MERGE_ON_READ");
    p.put("hoodie.datasource.write.recordkey.field", "id");
    p.put("hoodie.datasource.write.precombine.field", "ts");
    p.put("hoodie.datasource.write.partitionpath.field", "part");
    p.put("hoodie.table.cdc.enabled", String.valueOf(cdc));
    p.put("hoodie.table.cdc.supplemental.logging.mode", "data_before_after");
    p.put("hoodie.metadata.enable", "false");
    p.put("hoodie.compact.inline", "false");
    p.put("hoodie.compact.schedule.inline", "false");
    p.put("hoodie.compact.inline.max.delta.commits", "1");
    p.put("hoodie.clean.automatic", "false");
    p.put("hoodie.archive.automatic", "false");
    p.put("hoodie.log.compaction.enable", "false");
    p.put("hoodie.log.compaction.blocks.threshold", "3");
    p.put("hoodie.embed.timeline.server", "false");
    p.put("hoodie.write.markers.type", "DIRECT");
    p.put("hoodie.insert.shuffle.parallelism", "1");
    p.put("hoodie.upsert.shuffle.parallelism", "1");
    p.put("hoodie.bulkinsert.shuffle.parallelism", "1");
    p.put("hoodie.delete.shuffle.parallelism", "1");
    return p;
  }
  static void write(String path, Map<String,String> opts, int n) {
    Dataset<Row> df = spark.read().json(spark.createDataset(Arrays.asList(
        "{\"id\":\"a\",\"ts\":" + n + ",\"value\":\"a" + n + "\",\"part\":\"p\"}",
        "{\"id\":\"b\",\"ts\":" + n + ",\"value\":\"b" + n + "\",\"part\":\"p\"}"), Encoders.STRING()));
    df.coalesce(1).write().format("hudi").options(opts)
        .option("hoodie.datasource.write.operation", n == 0 ? "bulk_insert" : "upsert")
        .mode(SaveMode.Append).save(path);
  }
  static HoodieTableMetaClient meta(String path) {
    return HoodieTableMetaClient.builder().setConf(HadoopFSUtils.getStorageConf(jsc.hadoopConfiguration()))
        .setBasePath(path).setLoadActiveTimelineOnLoad(true).build();
  }
  static SparkRDDWriteClient client(String path, Map<String,String> opts) throws Exception {
    Properties p = new Properties(); p.putAll(opts);
    HoodieWriteConfig cfg = HoodieWriteConfig.newBuilder().withPath(path).forTable(opts.get("hoodie.table.name"))
        .withSchema(schema(path)).withProps(p).build();
    return new SparkRDDWriteClient(new HoodieSparkEngineContext(jsc), cfg);
  }
  static List<String> snapshot(String path) {
    return spark.read().format("hudi").load(path).select("id","ts","value","part").orderBy("id").toJSON().collectAsList();
  }
  static List<String> cdcRows(String path) {
    List<String> rows = new ArrayList<>(spark.read().format("hudi")
        .option("hoodie.datasource.query.type", "incremental")
        .option("hoodie.datasource.query.incremental.format", "cdc")
        .option("hoodie.datasource.read.begin.instanttime", "000")
        .load(path).toJSON().collectAsList());
    Collections.sort(rows);
    return rows;
  }

  static HoodieInstant latest(String path) {
    return meta(path).getActiveTimeline().getCommitsTimeline().filterCompletedInstants().lastInstant().get();
  }
  static void timeline(String path) throws Exception {
    HoodieTimeline t=meta(path).getActiveTimeline().getCommitsTimeline().filterCompletedInstants();
    for(HoodieInstant i:t.getInstantsAsStream().collect(Collectors.toList())) {
      HoodieCommitMetadata m=t.readCommitMetadata(i);
      System.out.println("TIMELINE requested="+i.requestedTime()+" completion="+i.getCompletionTime()+" action="+i.getAction()+" operation="+m.getOperationType()+" numWrites="+m.fetchTotalRecordsWritten()+" numUpdates="+m.fetchTotalUpdateRecordsWritten());
    }
  }
  static List<String> incremental(String path,String begin,String end,String reader,String label) throws Exception {
    DataFrameReader r=spark.read().format("hudi").option("hoodie.datasource.query.type","incremental")
      .option("hoodie.datasource.read.begin.instanttime",begin).option("hoodie.datasource.read.end.instanttime",end);
