    write(path,opts,0);
    for(int n=1;n<=3;n++)write(path,opts,n);
    HoodieInstant data=latest(path);
    List<String> before=snapshot(path);
    List<String> dataRows=incremental(path,"000",data.getCompletionTime(),"default",name+"_data_before");
    if(dataRows.size()!=2)throw new AssertionError("Expected 2 original rows");
    try(SparkRDDWriteClient c=client(path,opts)) {
      Option<String> i=c.scheduleLogCompaction(Option.empty());
      if(!i.isPresent())throw new AssertionError("Log compaction not scheduled");
      HoodieWriteMetadata result=c.logCompact(i.get());
      c.commitLogCompaction(i.get(),result,Option.empty());
    }
    HoodieInstant lc=latest(path);
    if(lc.requestedTime().equals(data.requestedTime()))throw new AssertionError("Missing completed log compaction");
    if(!before.equals(snapshot(path)))throw new AssertionError("Snapshot changed by log compaction");
    System.out.println("SNAPSHOT_UNCHANGED case="+name);
    System.out.println("SNAPSHOT_METADATA_AFTER="+spark.read().format("hudi").load(path).select("id","_hoodie_commit_time").orderBy("id").toJSON().collectAsList());
    timeline(path);
    for(String reader:Arrays.asList("default","true","false")) {
      // Start at the service request: after all input writes completed, before service completion.
      List<String> rows=incremental(path,lc.requestedTime(),lc.getCompletionTime(),reader,name+"_logcompaction_only");
      if(!rows.isEmpty())duplicates++;
      incremental(path,data.getCompletionTime(),lc.getCompletionTime(),reader,name+"_checkpoint_boundary");
    }
    Dataset<Row> update=spark.read().json(spark.createDataset(Collections.singletonList("{\"id\":\"a\",\"ts\":4,\"value\":\"a4\",\"part\":\"p\"}"),Encoders.STRING()));
    update.coalesce(1).write().format("hudi").options(opts).option("hoodie.datasource.write.operation","upsert").mode(SaveMode.Append).save(path);
    HoodieInstant next=latest(path);
    for(String reader:Arrays.asList("default","true","false")) {
      List<String> rows=incremental(path,next.requestedTime(),next.getCompletionTime(),reader,name+"_new_write_only");
      if(rows.size()!=1 || !rows.get(0).contains("a4"))throw new AssertionError("New write not read correctly: "+rows);
      List<String> mixed=incremental(path,lc.requestedTime(),next.getCompletionTime(),reader,name+"_logcompaction_plus_write");
      if(mixed.size()>1)duplicates++;
    }
    List<String> beforeRegular=snapshot(path);
    try(SparkRDDWriteClient c=client(path,opts)) {
      Option<String> i=c.scheduleCompaction(Option.empty());
      if(!i.isPresent())throw new AssertionError("Regular compaction not scheduled");
      HoodieWriteMetadata result=c.compact(i.get()); c.commitCompaction(i.get(),result,Option.empty());
    }
    HoodieInstant regular=latest(path);
    if(!beforeRegular.equals(snapshot(path)))throw new AssertionError("Snapshot changed by regular compaction");
    for(String reader:Arrays.asList("default","true","false")) {
      List<String> rows=incremental(path,regular.requestedTime(),regular.getCompletionTime(),reader,name+"_regular_compaction_only");
      if(!rows.isEmpty())throw new AssertionError("Regular compaction control reemits: "+rows);
    }
    for(String reader:Arrays.asList("default","true","false")) {
      List<String> historical=incremental(path,lc.requestedTime(),lc.getCompletionTime(),reader,name+"_historical_after_regular");
      if(!historical.isEmpty())duplicates++;
    }
    opts.put("hoodie.cleaner.policy","KEEP_LATEST_FILE_VERSIONS");
    opts.put("hoodie.cleaner.fileversions.retained","1");
    try(SparkRDDWriteClient c=client(path,opts)) { c.clean(); }
    System.out.println("AFTER_CLEAN_FILES="+Files.walk(Paths.get(path)).filter(p->p.getFileName().toString().endsWith(".parquet")).collect(Collectors.toList()));
    for(String reader:Arrays.asList("default","true","false")) {
      List<String> historical=incremental(path,lc.requestedTime(),lc.getCompletionTime(),reader,name+"_historical_after_clean");
      if(!historical.isEmpty())duplicates++;
    }
    System.out.println("CASE_COMPLETED="+name);
  }
