    if(!beforeRegular.equals(snapshot(path)))throw new AssertionError("Snapshot changed by regular compaction");
    for(String reader:Arrays.asList("default","true","false")) {
      List<String> rows=incremental(path,regular.requestedTime(),regular.getCompletionTime(),reader,name+"_regular_compaction_only");
      if(!rows.isEmpty())throw new AssertionError("Regular compaction control reemits: "+rows);
    }
    for(String reader:Arrays.asList("default","true","false")) {
      List<String> historical=incremental(path,lc.requestedTime(),lc.getCompletionTime(),reader,name+"_historical_after_regular");
      if(!historical.isEmpty())duplicates++;
    }
    opts.put("hoodie.cleaner.policy","KEEP_LATEST_FILE_VERSIONS");
    opts.put("hoodie.cleaner.fileversions.retained","1");
    try(SparkRDDWriteClient c=client(path,opts)) { c.clean(); }
    System.out.println("AFTER_CLEAN_FILES="+Files.walk(Paths.get(path)).filter(p->p.getFileName().toString().endsWith(".parquet")).collect(Collectors.toList()));
    for(String reader:Arrays.asList("default","true","false")) {
      List<String> historical=incremental(path,lc.requestedTime(),lc.getCompletionTime(),reader,name+"_historical_after_clean");
      if(!historical.isEmpty())duplicates++;
    }
    System.out.println("CASE_COMPLETED="+name);
  }
}

